import {createApi,SERVICES,totalFare,cashfreeCheckout} from './client.mjs';
import {updateMap} from './maps.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=createApi(window.PLANTO_CONFIG?.apiUrl||'');let user=null,service='shared',rides=[],trips=[],view='ride',watch=null,watchRide=null,toastTimer,searchVersion=0;
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const date=s=>new Date(s).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
const empty=(title,copy)=>`<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(copy)}</p></div>`;
const button=(label,action,id,cls='outline')=>`<button class="button ${cls} button-small" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;if($('#sheet').open){let error=$('#sheet-error');if(!error){error=document.createElement('p');error.id='sheet-error';error.className='error-message';error.setAttribute('role','alert');$('#sheet-body').prepend(error);}error.textContent=message;}clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,7000);}
async function safe(fn,element){if(element)element.disabled=true;try{await fn();}catch(e){toast(e.message);}finally{if(element)element.disabled=false;}}
function sheet(title,body){$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=body;$('#sheet').showModal();}
function auth(){if(user)return true;if($('#sheet').open)$('#sheet').close();show('account');toast('Sign in to continue.');return false;}
function show(name){view=name;$$('.view').forEach(v=>v.hidden=v.id!=='view-'+name);$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);b.setAttribute('aria-current',b.dataset.view===name?'page':'false');});const h=$('#view-'+name+' h1');h.tabIndex=-1;h.focus();window.scrollTo(0,0);if(name==='trips')void safe(refreshTrips);if(name==='drive')void safe(refreshOffers);if(name==='account'){renderAccount();if(user)void safe(async()=>{user=(await api.request('/v1/me')).user;renderAccount();});}}
function passengers(){const current=Number($('#seats').value)||1;$('#seats').innerHTML=Array.from({length:SERVICES[service].capacity},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');$('#seats').value=String(Math.min(current,SERVICES[service].capacity));}
function query(){return {origin:$('#from').value.trim(),destination:$('#to').value.trim(),date:$('#travel-date').value,seats:$('#seats').value,service,ladies:String($('#ladies').checked)};}
async function search(){const seq=++searchVersion;const q=query();updateMap({from:q.origin,to:q.destination});$('#route-summary').innerHTML=`<span class="eyebrow">${$('#ladies').checked?'LADIES · WOMEN WITH WOMEN':esc(SERVICES[service].label.toUpperCase())}</span><div class="route-line">${esc(q.origin)} → ${esc(q.destination)}</div>`;$('#results').innerHTML=empty('Checking availability…','Fetching journeys from approved drivers.');$('#result-count').textContent='';try{const data=await api.request('/v1/rides?'+new URLSearchParams(q));if(seq!==searchVersion)return;rides=data.rides;$('#result-count').textContent=`${rides.length} results`;$('#results').innerHTML=rides.length?rides.map(r=>`<article class="ride-card"><div class="ride-card-header"><div class="avatar">${esc(r.driver.slice(0,1))}</div><div><strong>${esc(r.driver)}</strong><small>Operator-approved driver</small></div><div class="fare">${money(r.price)}<small>${r.service==='shared'?'per seat':'vehicle total'}</small></div></div><p>${esc(r.vehicle)} · <strong>${esc(r.plate)}</strong></p><div class="ride-meta"><span>${esc(date(r.departure))}</span><span>${r.available} seats available</span></div>${r.ladies?'<span class="tag badge-ladies">Ladies · verified woman driver</span>':''}<div class="ride-card-bottom">${button('Review ride ↗','review',r.id,'dark')}</div></article>`).join(''):empty($('#ladies').checked?'No Ladies rides available.':'No rides available.','There are no matching driver offers. Try another route or time. No booking has been made.');}catch(e){if(seq===searchVersion){rides=[];$('#results').innerHTML=empty('Booking is currently unavailable.',e.message);}}}
async function refreshTrips(){if(!user){$('#trips').innerHTML=empty('Sign in to see your journeys.','Bookings are linked to your account.');return;}const data=await api.request('/v1/bookings');trips=data.bookings;$('#trips').innerHTML=trips.length?trips.map(b=>{const r=b.ride,driver=r.driver_id===user.id,active=['confirmed','in_progress'].includes(b.status);return `<article class="panel trip-card"><span class="tag">${esc(b.status.replace('_',' '))}</span> ${r.ladies?'<span class="tag badge-ladies">Ladies</span>':''}<h2>${esc(r.origin)} → ${esc(r.destination)}</h2><p>${esc(SERVICES[r.service].label)} · ${esc(date(r.departure))}<br>${esc(r.vehicle)} · ${esc(r.plate)}<br>${driver?'Rider: '+esc(b.rider_name):'Driver: '+esc(r.driver)} · ${money(b.total)}</p>${b.pin?`<p>Share this PIN only after checking your driver and vehicle.</p><div class="pin-display">${esc(b.pin)}</div>`:''}<div class="trip-actions">${!driver&&b.status==='confirmed'?button('Cancel booking','cancel',b.id):''}${driver&&b.status==='confirmed'?button('Enter rider PIN','start',b.id,'dark'):''}${driver&&b.status==='in_progress'?button('Complete trip','complete',b.id,'dark'):''}${!driver&&active?button('Share journey','share',b.id)+button('Revoke shared link','revoke',b.id):''}${driver&&active?button(watchRide===r.id?'Stop location sharing':'Share live location',watchRide===r.id?'stop-location':'location',r.id):''}${!driver&&b.status==='completed'&&!b.paid?button('Pay with Cashfree','pay',b.id,'dark')+button('Check payment','payment-status',b.id):''}</div>${b.paid?'<p>Payment verified by Cashfree.</p>':''}${active?b.location?`<p class="driver-location"><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps?q=${b.location.lat},${b.location.lng}">Open driver location ↗</a> · Updated ${esc(new Date(b.location.updated_at*1000).toLocaleTimeString())}</p>`:'<p class="muted">No recent driver location is available. Location is shared only with permission while the driver app is open.</p>':''}</article>`;}).join(''):empty('No journeys yet.','Your confirmed bookings will appear here.');}
async function refreshOffers(){if(!user){$('#offers').innerHTML=empty('Sign in as a driver.','Publish journeys after operator approval.');return;}const {rides:offers}=await api.request('/v1/driver/rides');$('#offers').innerHTML=offers.length?offers.map(r=>`<article class="panel"><h3>${esc(r.origin)} → ${esc(r.destination)}</h3><p>${esc(SERVICES[r.service].label)} · ${esc(r.status)} · ${esc(date(r.departure))}</p><p>${money(r.price)} · ${r.available}/${r.capacity} seats available</p>${r.status==='open'?button('Close offer','close',r.id):''}</article>`).join(''):empty('No offers yet.','Only your published journeys appear here.');}
function renderAccount(){$('#auth-form').hidden=!!user;$('#contact-form').hidden=!user;$('#account-title').textContent=user?'Hello, '+user.name+'.':'Let’s get you connected.';$('#account-details').innerHTML=user?`<div class="panel"><p>${esc(user.phone)} · ${esc(user.role)}</p><p>${user.approved?'Account approved by operator':'Verification pending. Contact the operator to complete identity, phone and, for drivers, vehicle checks.'}</p><p>${user.woman_verified?'Ladies eligibility verified':'Ladies eligibility has not been verified.'}</p><p class="muted">Account ID: ${esc(user.id)}</p></div>`:'';$('#contact').value=user?.contact||'';}
function openSOS(){if($('#sheet').open)$('#sheet').close();$('#call-contact').hidden=!user?.contact;if(user?.contact)$('#call-contact').href='tel:'+user.contact;$('#sos-dialog').showModal();}
async function shareText(text){if(navigator.share){await navigator.share({title:'Planto-Ride journey',text});return;}try{await navigator.clipboard.writeText(text);toast('Link copied. Send it to someone you trust.');}catch{sheet('Share this link',`<p class="share-link">${esc(text)}</p>`);}}
function stopWatch(){if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;watchRide=null;}
async function action(a,id){
 if(a==='review'){const r=rides.find(x=>x.id===id);if(!r)return;const seats=Number($('#seats').value);sheet('Review your ride',`<h3>${esc(r.origin)} → ${esc(r.destination)}</h3><p>${esc(r.driver)} · ${esc(r.vehicle)} · ${esc(r.plate)}<br>${esc(date(r.departure))}</p><p><strong>${money(totalFare(r,seats))}</strong> · ${seats} passenger(s) · pay after completion</p>${r.ladies?'<label class="check-row"><input id="women-party" type="checkbox"><span>I confirm every passenger in my party is a woman.</span></label>':''}<p>Check vehicle details before boarding. Your trip begins only after your driver enters your PIN.</p>${button('Confirm booking','book',r.id,'dark')}`);return;}
 if(!auth())return;
 if(a==='book'){const r=rides.find(x=>x.id===id);await api.request('/v1/bookings','POST',{ride_id:id,seats:Number($('#seats').value),women_party:!!$('#women-party')?.checked});$('#sheet').close();await refreshTrips();show('trips');toast('Booking confirmed. Your trip-start PIN is in My trips.');return;}
 if(a==='cancel'){sheet('Cancel this booking?',`<p>This releases your reserved seats. No online payment is collected before the trip.</p>${button('Confirm cancellation','cancel-confirm',id,'dark')}`);return;}
 if(a==='cancel-confirm'){await api.request('/v1/bookings/'+id+'/cancel','POST',{});$('#sheet').close();await refreshTrips();return;}
 if(a==='start'){sheet('Verify rider PIN',`<p>Ask for the PIN only after the rider has checked your details.</p><form id="pin-form" data-id="${esc(id)}"><label>Six-digit PIN<input name="pin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"></label><button class="button dark">Start trip</button></form>`);return;}
 if(a==='complete'){sheet('Complete this trip?',`<p>Confirm the passenger has reached their destination. The final fare will become payable.</p>${button('Confirm completion','complete-confirm',id,'dark')}`);return;}
 if(a==='complete-confirm'){await api.request('/v1/bookings/'+id+'/complete','POST',{});$('#sheet').close();await refreshTrips();if(watchRide&&!trips.some(b=>b.ride.id===watchRide&&['confirmed','in_progress'].includes(b.status)))stopWatch();return;}
 if(a==='share'){const data=await api.request('/v1/bookings/'+id+'/share','POST',{});sheet('Share your journey',`<p>Anyone with this link can see the route, vehicle and recent driver location. It expires in two hours or when your trip ends.</p><p class="share-link">${esc(data.url)}</p><button class="button dark" id="send-share">Choose how to share</button>`);$('#send-share').onclick=()=>safe(()=>shareText(data.url));return;}
 if(a==='revoke'){await api.request('/v1/bookings/'+id+'/share','DELETE');toast('Journey sharing link revoked.');return;}
 if(a==='close'){await api.request('/v1/rides/'+id+'/close','POST',{});await refreshOffers();return;}
 if(a==='location'){if(!navigator.geolocation)throw Error('Location is not supported on this device.');stopWatch();watchRide=id;watch=navigator.geolocation.watchPosition(p=>{void safe(()=>api.request('/v1/rides/'+id+'/location','POST',{lat:p.coords.latitude,lng:p.coords.longitude}));},e=>{stopWatch();toast('Location could not be shared: '+e.message);},{enableHighAccuracy:true,maximumAge:10000,timeout:15000});toast('Location sharing requested. Keep this page open.');await refreshTrips();return;}
 if(a==='stop-location'){stopWatch();await api.request('/v1/rides/'+id+'/location','DELETE');await refreshTrips();return;}
 if(a==='pay'){const p=await api.request('/v1/bookings/'+id+'/payment','POST',{});await cashfreeCheckout(p);const status=await api.request('/v1/bookings/'+id+'/payment-status','POST',{});toast(status.paid?'Payment verified. Thank you.':'Payment not confirmed yet. Use Check payment before retrying.');await refreshTrips();return;}
 if(a==='payment-status'){const status=await api.request('/v1/bookings/'+id+'/payment-status','POST',{});toast(status.paid?'Payment verified.':'Payment is not yet confirmed by Cashfree.');await refreshTrips();}
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-sos'))openSOS();else if(b.dataset.view)show(b.dataset.view);else if(b.dataset.service){service=b.dataset.service;$$('[data-service]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));passengers();void search();}else if(b.dataset.action)void safe(()=>action(b.dataset.action,b.dataset.id),b);});
$('#search-form').onsubmit=e=>{e.preventDefault();void safe(search,e.submitter);};$('#ladies').onchange=()=>void search();
$('#auth-mode').onchange=()=>{const register=$('#auth-mode').value==='register';$('#register-fields').hidden=!register;$('#name').required=register;$('#password').autocomplete=register?'new-password':'current-password';};
$('#auth-form').onsubmit=e=>{e.preventDefault();void safe(async()=>{const mode=$('#auth-mode').value;const input={phone:$('#phone').value,password:$('#password').value,...(mode==='register'?{name:$('#name').value,role:$('#role').value,gender:$('#gender').value}:{})};const data=await api.request('/v1/auth/'+mode,'POST',input);user=data.user;api.setToken(data.token);$('#password').value='';renderAccount();toast(user.approved?'Signed in.':'Account created. Operator verification is required before travel.');},e.submitter);};
$('#contact-form').onsubmit=e=>{e.preventDefault();void safe(async()=>{await api.request('/v1/me','PATCH',{contact:$('#contact').value});user.contact=$('#contact').value;toast('Trusted contact saved.');},e.submitter);};
$('#logout').onclick=()=>void safe(async()=>{await api.request('/v1/auth/session','DELETE');stopWatch();api.setToken('');user=null;trips=[];renderAccount();});
$('#offer-form').onsubmit=e=>{e.preventDefault();if(!auth())return;void safe(async()=>{const f=new FormData(e.target);await api.request('/v1/rides','POST',{origin:f.get('origin'),destination:f.get('destination'),departure:new Date(f.get('departure')).toISOString(),service:f.get('service'),ladies:f.has('ladies'),capacity:Number(f.get('capacity')),price:Number(f.get('price')),vehicle:f.get('vehicle'),plate:f.get('plate')});toast('Journey published.');await refreshOffers();},e.submitter);};
$('#report-form').onsubmit=e=>{e.preventDefault();if(!auth())return;void safe(async()=>{const r=await api.request('/v1/incidents','POST',{kind:'safety',detail:$('#report-detail').value});$('#report-detail').value='';toast(r.message+' Reference: '+r.id);},e.submitter);};
document.addEventListener('submit',e=>{if(e.target.id!=='pin-form')return;e.preventDefault();void safe(async()=>{await api.request('/v1/bookings/'+e.target.dataset.id+'/start','POST',{pin:new FormData(e.target).get('pin')});$('#sheet').close();await refreshTrips();},e.submitter);});
$('#refresh-trips').onclick=()=>void safe(refreshTrips);$('#close-sheet').onclick=()=>$('#sheet').close();$('#close-sos').onclick=()=>$('#sos-dialog').close();
$('#share-location').onclick=()=>{if(!navigator.geolocation){$('#sos-status').textContent='Location is unavailable. Call 112 or your contact and describe your location.';return;}$('#sos-status').textContent='Requesting your location…';navigator.geolocation.getCurrentPosition(p=>{const url=`https://www.google.com/maps?q=${p.coords.latitude},${p.coords.longitude}`;$('#sos-status').textContent='Your location: '+url+'\nNothing has been sent yet. Choose Share to send it.';const b=document.createElement('button');b.className='button dark';b.textContent='Share this location';b.onclick=()=>void safe(()=>shareText('I need help. My location: '+url));$('#sos-status').append(document.createElement('br'),b);},()=>$('#sos-status').textContent='Location unavailable or permission denied. Call 112 and describe your surroundings.',{enableHighAccuracy:true,timeout:15000,maximumAge:0});};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&watch!==null){const id=watchRide;stopWatch();void api.request('/v1/rides/'+id+'/location','DELETE').catch(()=>{});toast('Location sharing stopped while this page is hidden.');}});
const today=new Date();$('#travel-date').value=new Date(today.getTime()-today.getTimezoneOffset()*60000).toISOString().slice(0,10);$('#travel-date').min=$('#travel-date').value;passengers();void search();renderAccount();
void api.request('/health').then(h=>{$('#connection').textContent='Booking service connected · '+(h.payments_configured?(h.payment_mode==='production'?'Cashfree live payments':'Cashfree test mode'):'Online payments not configured');}).catch(()=>{$('#connection').textContent='Bookings unavailable · service connection pending';$('#connection').classList.add('offline');});
setInterval(()=>{if(user&&view==='trips'&&!document.hidden&&!$('#sheet').open&&!$('#sos-dialog').open)void refreshTrips().catch(()=>{});},15000);
